(* [comment removed for export] *)
Inductive went : Type :=
| WSt (a : saddr) (wd : nat) (v : expr)                       (* [comment removed for export] *)
| WCopy (db : expr) (dk : Z) (sb : expr) (sk : Z) (n : Z)     (* [comment removed for export] *)
| WFill (db : expr) (dk : Z) (n : Z) (c : Z).                 (* [comment removed for export] *)

Fixpoint wden (E : env) (M : word -> option byte) (w : list went) : word -> option byte :=
  match w with
  | [] => M
  | WSt a wd v :: r => wbytes (wden E M r) (adenot E a) (word_to_le_bytes wd (edenot E v))
  | WCopy db dk sb sk n :: r =>
      let m := wden E M r in
      match rdn segs m (adenot E (SA sb sk)) (Z.to_nat n) with
      | Some bs => wbytes m (adenot E (SA db dk)) bs
      | None => m
      end
  | WFill db dk n c :: r => wbytes (wden E M r) (adenot E (SA db dk)) (repeat (Z_to_bv 8 c) (Z.to_nat n))
  end.

Fixpoint wlog (log : list sentry) : list went :=
  match log with [] => [] | SE a wd v :: r => WSt a wd v :: wlog r end.

Lemma wden_wlog : forall E M log w, wden E M (wlog log ++ w) = mem_denot E (wden E M w) log.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S<0|30;%~R!1+1!1,2|600;!1+3!1+1!1,20!1+4+5!1';#1!3'9#4#3#1!1,>+5!3,?+5#3#2!3'9#=#<#:!3'<#=7#2!2'E#>#6!2'F#5!2'G#>#4!3,?+5!3,H#5#4#3#2$E;R+0$M;R1$log;R2$w;R!1+4+6!5'7+5$log;R2!3+81!3'9#5#4!3':+63#2!3'<#5!3'9#5#4#2#1vd!2,=14!3+81!3'9#4#3!3':+6!1';5#1!3'<#445$a0;R+5-5RN$s;R+5%l;R2%~R!3+81!3'9#7#6!3':+63#4!3'<#7!3'9#7#6#4#1!3+81!3'9#8#7!3':+6!1';6#5!3'<#8!3'9#8#7#56#11$e_addr;R+@$e_width;R+A$e_val;R+B!3$a;R+@$wd;R+A$v;R+B$r;R2$IH;R!3+81!3'9#<#;!3':+63#9!3'<#<!3'9#<#;#9#1vd!6'C18$o;R1!3+81!3'D#19:!3'D!3'<#>!3'9#>#=#;#39:!2,=1!3'D8!2'E#=#5!2'F#4!2'G#=#3!3'9#=#<!3':+6!1';#2#:#1!3+81!3'9#=#<!3':+6!1';;#:!3'<#=7;#3#2#1#2").
Qed.

(* [comment removed for export] *)
Definition went_vars_lt (b : nat) (g : went) : bool :=
  match g with
  | WSt a _ v => APC.expr_vars_lt b (a_base a) && APC.expr_vars_lt b v
  | WCopy db _ sb _ _ => APC.expr_vars_lt b db && APC.expr_vars_lt b sb
  | WFill db _ _ _ => APC.expr_vars_lt b db
  end%bool.
Definition wl_vars_lt (b : nat) (w : list went) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$b;R+A$w;R!1+4+6!3'I+6!1'J#2#1").

Lemma edenot_agree_AP : forall b E E' e, env_agree b E E' -> APC.expr_vars_lt b e = true -> edenot E e = edenot E' e.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!2,=+L,N%H;R!3+8+L!2'M#8#1,N!3+8+L!2'Q#9#2,N%H;R!3+8+L!2'M#:#1,N!3+8+L!2'Q#;#2,N$b;R+A$E;R+0$E';R+0$e;R+B$Hag;R!3'K#4#3#2$H;R!3+8+L!2'M#5#2,N!6'O#6#5#4#3#2!;'P$e;R+B%H;R!3+8+L!2'M#7#1,N!3+8+L!2'Q#8#2,N$z;R+R$H;R!3+8+L!2'M#7!1,S#1,Nvd0!3+8+L!2'Q#8!1,S#2,N$n;R+A$H;R!3+8+L!2'M#7!1,T#1,Nvd#1!3+8+L!2'Q#8!1,T#2,N$op;R+U$e1;R+B$IHe1;R1$e2;R+B$IHe2;R2$H;R!3+8+L!2'M#;!3,V#5#4#2,Nvd#1!3+8+L!2'Q#<!3,V#6#5#3,N$op;R+U$e1;R+B$IHe1;R1$e2;R+B$IHe2;R2$H;R!3+8+L!2'M#;!3,W#5#4#2,Nvd#1!3+8+L!2'Q#<!3,W#6#5#3,N$op;R+X$e1;R+B$IHe1;R1$e2;R+B$IHe2;R2$H;R!3+8+L!2'M#;!3,Y#5#4#2,Nvd#1!3+8+L!2'Q#<!3,Y#6#5#3,N$op;R+X$e1;R+B$IHe1;R1$e2;R+B$IHe2;R2$H;R!3+8+L!2'M#;!3,Z#5#4#2,Nvd#1!3+8+L!2'Q#<!3,Z#6#5#3,N$sx;R+L$lo;R+A$n;R+A$e;R+B$IHe;R2$H;R!3+8+L!2'M#;!4,[#5#4#3#2,Nvd#1!3+8+L!2'Q#<!4,[#6#5#4#3,N$sx;R+L$k;R+A$i;R+R$n;R+A$H;R!3+8+L!2'M#:!4,\#4#3#2#1,Nvd0!3+8+L!2'Q#;!4,\#5#4#3#2,N#3#1").
