Lemma reg_sound1 : forall E ss R, regs_ok E (s_regs ss) R -> getr R 1%bv = edenot E (reg ss 1).
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1,2|21;$E;R+0$ss;R+_F$R;R!2'a<0!1+1!1,2|600;$HR;R!3'a=#3!1'_H#2#1!1#1!3,b:0!1,_L,_?,aH").
Qed.
