(* [comment removed for export] *)
Lemma fld_run : forall n (fx : FPState) p ss E R (m : word -> option byte) allkn,
  fld_sources_ok p n ss = true ->
  regs_ok E (s_regs ss) R -> know_ok segs E m allkn -> allkn = s_know ss ->
  exists fx' : FPState,
