Definition region : Type := (expr * Z * Z)%type.
Definition within1 (b : expr) (k len : Z) (r : region) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S10!2+_R+B+R$b;R+B$k;R+R$len;R+R$r;R'iV-_RRN$r;R!2+_R0+R+L#11$p;R0$rlen;R+R-_RRN$p;R!2+_R+B+R+L#21$rb;R+B$rlo;R+R!2'^2!2'^2!2'^2!2'`P#8#2!2'_M,^W#6!2'_O#1#7!2'_O!2'`4#7#6!2'`4#1#3").
Definition went_within (F : list region) (g : went) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S01lgiV;g`Jd;$F;R!1+4'iV$g;R+6-6RN$g;R+6+L#13$a;R+@$wd;R+A$v;R+B-@RN$a;R+@+L#31$b;R+B$k;R+R!3'`J'iV!3'iW#2#1!1'^P#4#7$db;R+B$dk;R+R$sb;R+B$sk;R+R$n;R+R!2'^2!2'_O,^W#1!3'`J'iV!3'iW#5#4#1#7$db;R+B$dk;R+R$n;R+R$c;R+R!2'^2!2'_O,^W#2!3'`J'iV!3'iW#4#3#2#6").
Definition regions_flat (E : env) (F : list region) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S31lgiV;gbTd;!2+_R+B+R!2'cF#7!2,^6#2#1|10;$E;R+0$F;R!1+4'iV!3+bT'iV$r;R'iV-_RRN$r;R!2+_R0+Rw#11$p;R0$rlen;R+R-_RRN$p;R!2+_R+B+Rw#21$rb;R+B$rlo;R+R!2+^3!2'^T,^W1!2'^T!2'`41#3!2'bG!1,_L2!1,_L|600;#1").
Definition outside (E : env) (F : list region) (a : word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S40!1,2|600;!2+_R+B+R!2'bD0#6!2'cF#8!2,^6#2#1$E;R+0$F;R!1+4'iV$a;R!1+10!3+bT'iV$r;R'iV-_RRN$r;R!2+_R1+Rw#11$p;R1$rlen;R+R-_RRN$p;R!2+_R+B+Rw#21$rb;R+B$rlo;R+R!2+c1!2'^O23!2'^T!2'`43#32#2").

Lemma within1_sound : forall E b k len rb rlo rlen (a : word),
  within1 b k len (rb, rlo, rlen) = true ->
