Definition region_flat_chk (kn : list kentry) (r : region) : bool :=
  let '(rb, rlo, rlen) := r in
  match rb with
  | ELit 0 => (Z.leb 0 rlo && Z.ltb 0 rlen && Z.ltb (rlo + rlen) two64)%bool
  | _ => (Z.ltb 0 rlen && existsb (fun K => match K with
                         | KWr (SA b lo) (ELit len) => (expr_eqb b rb && Z.leb lo rlo && Z.leb (rlo + rlen) (lo + len) && Z.ltb len two64 && Z.leb 0 len)%bool
                         | _ => false end) kn)%bool
  end.
Definition post_ok (ps : post_spec) (ss : sym_state) (w : list went) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 3 "S20!2+_R+A+B!1'j5#3$ps;R+j2$ss;R+_F$w;R!1+4+6!2'^2!2'^2!2'^2!2'^2!2'_J!1'_Z#2!1'j3#3!3'I0$ie;R0!2'`P!4'_G+B!3'eJ+A+B#1!1'_H#3!1,S,^W!3'eK+A+B#1!1'j4#3!3'I+6!1'iX1#1!3'I'iV!1'j6!1'_W#21!3'I+_S$K;R+_S!3'`J+_S!1'j7#1!1'_W#3!1'j8#3").

