Definition regions_ok (E : env) (F : list region) : Prop :=
  Forall (fun r : region => let '(rb, rlo, rlen) := r in
            0 <= estart E (SA rb rlo) /\ 0 < rlen < 2 ^ 64 /\ estart E (SA rb rlo) + rlen <= 2 ^ 64) F.
